    months = {'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6, 'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12}
    dt = datetime.strptime(f'{day} {month} {year} {hour}:{minute}:{second}', '%d %b %Y %H:%M:%S')
    tz_delta = int(tz_offset[:3]) * 3600 + int(tz_offset[0] + tz_offset[3:]) * 60
    epoch_micros = int((dt - datetime(1970, 1, 1)).total_seconds() * 1000000) - tz_delta * 1000000
    layout = [len(sp1), months[month]]
    return {'stored': [epoch_micros], 'layout': layout}

